/**
 * Climate and weather.
 *
 * Years carry anomalies from two oscillations (a ~6-year "El Niño-like" cycle
 * and a ~25-year drought cycle) plus autocorrelated noise and an optional
 * warming trend. Days are generated by a weather generator with persistence:
 * temperature/humidity/wind AR(1) states, a Markov wet/dry chain, summer
 * convective storms with (sometimes dry) lightning, and multi-day dry
 * downslope wind events in late summer and autumn — the valley's fire weather.
 */
import { clamp, clamp01 } from '../grid.ts';
import { MEAN_T_REF, SEASON_AMP } from '../env.ts';
import type { World } from '../world.ts';

/** Climatological wet-day probability by day of year (0 = first day of spring). */
function wetProb(doy: number): number {
  const m = Math.floor(doy / 30);
  return [0.32, 0.3, 0.26, 0.2, 0.15, 0.13, 0.15, 0.2, 0.26, 0.33, 0.33, 0.33][m];
}
/** Mean precipitation per month (mm) at the reference elevation. */
function monthPrecip(doy: number): number {
  const m = Math.floor(doy / 30);
  return [52, 50, 46, 38, 28, 22, 24, 32, 42, 56, 58, 56][m];
}
/** Probability of a convective (lightning) storm on a given day. */
function stormProb(doy: number): number {
  const m = Math.floor(doy / 30);
  return [0, 0.01, 0.04, 0.1, 0.15, 0.15, 0.1, 0.04, 0.01, 0, 0, 0][m];
}
/** Probability a downslope wind event starts. */
function windEventProb(doy: number): number {
  const m = Math.floor(doy / 30);
  return [0.006, 0.004, 0.002, 0.002, 0.004, 0.01, 0.025, 0.03, 0.02, 0.008, 0.006, 0.006][m];
}

export function seasonalTemp(doy: number): number {
  return MEAN_T_REF + SEASON_AMP * Math.cos((2 * Math.PI * (doy - 120)) / 360);
}

/** Called on the first day of each year. */
export function newClimateYear(w: World): void {
  const c = w.climate;
  const r = w.rng.weather;
  if (w.day === 0) {
    c.periodA = r.range(5, 8);
    c.periodB = r.range(20, 32);
    c.phaseA = r.range(0, Math.PI * 2);
    c.phaseB = r.range(0, Math.PI * 2);
  } else {
    c.phaseA += (2 * Math.PI) / c.periodA;
    c.phaseB += (2 * Math.PI) / c.periodB;
  }
  const harsh = w.config.difficulty === 'harsh' ? 0.06 : w.config.difficulty === 'gentle' ? -0.05 : 0;
  const anomaly = 0.15 * Math.sin(c.phaseA) + 0.12 * Math.sin(c.phaseB) + 0.35 * c.carry + r.normal(0, 0.11) - harsh;
  c.carry = anomaly;
  c.yearWet = clamp(1 + anomaly, 0.55, 1.45) * w.config.dryness;
  const yearsIn = w.yearsElapsed;
  c.yearTemp = (c.trendPerDecade * yearsIn) / 10 + 0.5 * Math.sin(c.phaseA + 1.3) - 0.4 * anomaly + r.normal(0, 0.35);
  c.snowpackPeak = 0;
}

export function generateWeather(w: World): void {
  const c = w.climate;
  const r = w.rng.weather;
  const wx = w.weather;
  const doy = w.doy;
  const season = Math.floor(doy / 90);

  // Temperature: seasonal cycle + yearly anomaly + AR(1) daily anomaly.
  c.tempAR = 0.75 * c.tempAR + r.normal(0, 2.1);
  const base = seasonalTemp(doy) + c.yearTemp;
  // Precipitation occurrence with persistence.
  let pw = wetProb(doy) * clamp(0.6 + 0.4 * c.yearWet, 0.5, 1.3);
  if (wx.precip > 0.5) pw = Math.min(0.75, pw * 1.6);
  else pw *= 0.85;
  const wet = r.next() < pw;
  let precip = 0;
  if (wet) {
    const mean = (monthPrecip(doy) * c.yearWet) / (30 * wetProb(doy));
    precip = r.exponential(mean);
  }
  // Convective storms in summer.
  const storm = r.next() < stormProb(doy) * clamp(0.7 + 0.5 * (c.yearTemp + 1) / 2, 0.5, 1.5);
  let dry = false;
  let strikes = 0;
  if (storm) {
    strikes = r.poisson(6 * (1 + Math.max(0, c.yearTemp) * 0.2));
    dry = r.next() < 0.25 + 0.45 * c.droughtIndex;
    precip = dry ? r.range(0, 1.5) : Math.max(precip, r.range(3, 16));
  }
  // Downslope wind events: multi-day, dry, strong, blowing toward the outlet.
  if (c.windEventDays > 0) c.windEventDays--;
  else if (!wet && r.next() < windEventProb(doy) * (0.6 + 0.8 * c.droughtIndex)) c.windEventDays = r.intRange(1, 3);
  const windEvent = c.windEventDays > 0;
  if (windEvent) precip = 0;

  // Humidity
  c.rhAR = 0.6 * c.rhAR + r.normal(0, 0.06);
  const rhSeason = [0.5, 0.35, 0.45, 0.68][season];
  let rh = rhSeason + c.rhAR + (precip > 0.5 ? 0.25 : 0) - 0.008 * c.tempAR * 3 - (1 - c.yearWet) * 0.15;
  if (windEvent) rh = r.range(0.06, 0.16);
  if (storm && dry) rh = Math.min(rh, r.range(0.15, 0.3));
  rh = clamp(rh, 0.06, 1);

  // Wind
  c.windAR = 0.55 * c.windAR + r.normal(0, 0.35);
  let windSpeed = Math.exp(Math.log(3.2) + c.windAR + (season === 0 ? 0.15 : 0));
  let windDir = r.normal(0, 0.55); // prevailing westerlies blow toward +x
  if (windEvent) {
    windSpeed = r.range(10, 17);
    const outletDir = w.outletCell >= 0 && w.outletCell % w.W === 0 ? Math.PI : 0;
    windDir = outletDir + r.normal(0, 0.18);
  }
  if (storm) windSpeed = Math.max(windSpeed, r.range(5, 11)); // outflow gusts
  windSpeed = clamp(windSpeed, 0.3, 20);

  const temp = base + c.tempAR + (windEvent ? 2 : 0) - (precip > 2 ? 2 : 0);
  const range = [7, 9, 8, 5][season];
  wx.temp = temp;
  wx.tmax = temp + range;
  wx.tmin = temp - range;
  wx.precip = precip;
  wx.rh = rh;
  wx.windSpeed = windSpeed;
  wx.windDir = windDir;
  wx.storm = storm;
  wx.strikes = strikes;
  wx.dryLightning = storm && dry;
  wx.windEvent = windEvent;
  if (wx.tmin < c.winterMin && season >= 2) c.winterMin = wx.tmin - 6; // valley-floor coldest night proxy
  if (doy === 0) c.winterMin = Math.min(c.winterMin, -8);

  // Drought index (KBDI-like): dries with heat, recovers with rain.
  const dry1 = Math.max(0, temp + 2) * 0.0016 * (1 + 0.6 * (1 - rh));
  c.droughtIndex = clamp01(c.droughtIndex + dry1 - precip * 0.0045);
  // smoke dispersion: calm, cold, humid days trap smoke in the valley
  wx.dispersion = clamp01(0.2 + windSpeed / 9 + (season === 1 ? 0.15 : 0) - (season === 3 ? 0.2 : 0));
  w.counters.yearPrecip += precip;
}

/** Diurnal multipliers for a 3-hour sub-step (sub 0 = 00:00-03:00). */
export function diurnal(sub: number): { wind: number; fmAdd: number; spread: number } {
  // hour at centre of the sub-step
  const h = sub * 3 + 1.5;
  const sun = Math.max(0, Math.sin(((h - 6) / 12) * Math.PI)); // 0 at night, peak 12:00
  const afternoon = Math.max(0, Math.sin(((h - 8) / 14) * Math.PI)); // peak ~15:00
  return {
    wind: 0.55 + 0.75 * afternoon,
    fmAdd: 0.05 * (1 - sun) - 0.02 * afternoon,
    spread: 0.45 + 0.75 * afternoon,
  };
}

/** Recompute the valley fire-danger rating from median fuel moisture, wind and drought. */
export function updateDanger(w: World, medianFm: number): void {
  const wx = w.weather;
  const dryness = clamp01((0.28 - medianFm) / 0.22);
  const windF = 0.55 + 0.45 * clamp01(wx.windSpeed / 12);
  const d = clamp01(Math.pow(dryness, 1.15) * windF * (0.75 + 0.45 * w.climate.droughtIndex));
  wx.danger = d;
  wx.dangerClass = d < 0.15 ? 0 : d < 0.32 ? 1 : d < 0.52 ? 2 : d < 0.72 ? 3 : 4;
}

export const DANGER_NAMES = ['Low', 'Moderate', 'High', 'Very High', 'Extreme'] as const;
